import{services,serviceLabel,money,today,addDays,slots,validHours,escapeHTML as esc}from'./model.js';
import{zipFiles}from'./zip.js';
const $=s=>document.querySelector(s),content=$('#admin-content'),dialog=$('#client-dialog');let refreshVersion=0;let state,view=location.hash.slice(1)||'overview',search='',timer,includeArchived=false,from=today().slice(0,7)+'-01',to=today();
const labels={overview:'Resumen',bookings:'Citas',clients:'Clientes',finance:'Finanzas',materials:'Materiales',suppliers:'Proveedores',orders:'Pedidos',documents:'Documentos',notifications:'Avisos',schedule:'Horario'};if(!labels[view])view='overview';
const title={overview:'Tu salón.<br>Todo bajo control.',bookings:'Cada cita.<br>En su momento.',clients:'Tus clientes.<br>Cada detalle cuenta.',finance:'Finanzas.<br>Ingresos y gastos en orden.',materials:'Tu catálogo.<br>Hasta el último matiz.',suppliers:'Proveedores.<br>Relaciones que suman.',orders:'Tus compras.<br>Todo en orden.',documents:'Documentos.<br>Siempre a mano.',notifications:'Cada solicitud.<br>Un aviso a tiempo.',schedule:'Tu ritmo.<br>Tus reglas.'};
const statuses={pending:'Pendiente de confirmar',confirmed:'Confirmada',completed:'Completada',cancelled:'Cancelado',draft:'Borrador',ordered:'Pedido preparado',received:'Recibido'};const kinds={invoice_received:'Factura recibida',invoice_issued:'Factura emitida',receipt:'Justificante de pago',contract:'Contrato',photo:'Foto / captura',other:'Otro'};
const paymentMethods={cash:'Efectivo',card:'Tarjeta',transfer:'Transferencia',other:'Otro / sin especificar'};
const fn=c=>[c.firstName,c.lastName].filter(Boolean).join(' '),service=id=>{const s=services.find(s=>s.id===id);return s?serviceLabel(s):id},eu=c=>money((c||0)/100),active=rows=>rows.filter(x=>includeArchived||!x.archived),options=(rows,field='name',value='')=>'<option value="">Sin seleccionar</option>'+rows.filter(r=>!r.archived||r.id===value).map(r=>`<option value="${r.id}" ${r.id===value?'selected':''}>${esc(typeof field==='function'?field(r):r[field])}${r.archived?' (archivado)':''}</option>`).join('');
async function api(path,method='GET',body){const r=await fetch('/api/admin/'+path,{method,headers:body instanceof FormData?{}:{'Content-Type':'application/json'},body:body?body instanceof FormData?body:JSON.stringify(body):undefined});const data=await r.json();if(!r.ok)throw Error(data.error||'No se han podido guardar los datos.');return data}
function feedback(s){clearTimeout(timer);$('#admin-feedback').textContent=s;timer=setTimeout(()=>$('#admin-feedback').textContent='',6500)}
async function refresh(){const version=++refreshVersion;try{const next=await api('state');if(version!==refreshVersion)return;state=next;render()}catch(e){if(version!==refreshVersion)return;content.innerHTML=`<div class="panel mini-panel"><h3>Base de datos no disponible</h3><p>${esc(e.message)}</p><button class="compact-button" id="retry">Reintentar</button></div>`;$('#retry').onclick=refresh}}
function switchView(v){view=labels[v]?v:'overview';search='';includeArchived=false;location.hash=view;render();window.scrollTo({top:0,behavior:'instant'})}
function render(){if(!state)return;$('#admin-section').value=view;$('#session-mode').textContent=state.mode==='local'?'Modo local':'Sesión protegida · 1 mes';$('#logout-link').hidden=state.mode==='local';document.querySelector('.demo-pill').textContent=state.mode==='local'?'BASE LOCAL · D1 / R2':'CULT SPAIN · GESTIÓN';document.querySelector('.demo-note').textContent=state.mode==='local'?'Los datos se guardan en la base de este ordenador. Los servicios y horarios son de ejemplo. Sin pagos online.':'Servicios y horarios de ejemplo. Los datos y originales se guardan en Cloudflare. Sin pagos online.';$('#admin-title').innerHTML=title[view];$('#breadcrumb').textContent=labels[view];document.querySelectorAll('.sidebar [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));({overview,bookings,clients:clientView,finance,materials:materialView,suppliers:supplierView,orders:orderView,documents:documentView,notifications:notificationView,schedule})[view]()}
function toolbar(name,sub,tools=''){return `<div class="table-toolbar"><div><h2>${name}</h2>${sub?`<p>${sub}</p>`:''}</div><div class="tools">${tools}</div></div>`}
function table(headers,rows,kind=''){return `<div class="table-scroll ${kind?'finance-table-scroll':''}" tabindex="0" role="region" aria-label="Tabla de registros"><table ${kind?`class="finance-record-table ${rows?'':'is-empty'}" data-record-type="${kind}"`: ''}><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty-table"><strong>Todavía no hay registros</strong>Añade el primer registro.</td></tr>`}</tbody></table></div>`}
const btn=(label,attr,cls='compact-button')=>`<button class="${cls}" ${attr}>${label}</button>`;
const kpi=(label,value,note,target,action='view')=>`<button class="kpi" data-${action}="${target}"><label>${label}</label><strong>${value}</strong><small>${note}</small></button>`;
function recordActions(type,r){return btn('Editar',`data-edit="${type}" data-id="${r.id}"`)+btn(r.archived?'Restaurar':'Archivar',`data-archive="${type}" data-id="${r.id}"`)}
function filterTools(type,label){return `<input id="search" aria-label="Buscar" placeholder="Buscar…" value="${esc(search)}">${btn(includeArchived?'Ocultar archivo':'Mostrar archivo','id="toggle-archive"')}${btn('+ '+label,`data-new="${type}"`)}`}
function bindFilters(){if($('#search'))$('#search').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};if($('#toggle-archive'))$('#toggle-archive').onclick=()=>{includeArchived=!includeArchived;render()}}
const receiptFor=bookingId=>state.incomes.find(x=>x.bookingId===bookingId);
function receiptAction(b){const r=receiptFor(b.id);return r?btn(r.archived?'Revisar ingreso archivado':'Editar ingreso',`data-edit="incomes" data-id="${r.id}"`):btn('Registrar cobro',`data-new-income-booking="${b.id}"`)}
const matches=(...s)=>s.join(' ').toLowerCase().includes(search.toLowerCase());
function bookingTable(rows){return table(['Fecha / hora','Cliente','Servicio','Importe','Estado','Pagado','Acciones'],rows.map(b=>`<tr><td>${esc(b.date)}<small>${esc(b.time)}</small>${btn('Gestionar',`data-manage-booking="${b.id}"`,'compact-button mobile-booking-manage')}</td><td><button class="row-action" data-client="${b.clientId}">${esc(b.name)}</button><small>${esc(b.phone)}</small></td><td>${esc(service(b.service))}</td><td>${b.price===null?'Sin registrar':money(b.price)}</td><td><span class="status-tag ${b.status==='completed'?'done':''}">${statuses[b.status]}</span></td><td>${money(b.paid)}</td><td>${['pending','confirmed'].includes(b.status)?(b.status==='pending'?btn('Confirmar',`data-booking="confirm" data-id="${b.id}"`):'')+btn('Cambiar fecha / hora',`data-booking="reschedule" data-id="${b.id}"`)+(b.status==='confirmed'?btn('Completar',`data-booking="complete" data-id="${b.id}"`):'')+btn(b.status==='pending'?'Rechazar':'Cancelar',`data-booking="cancel" data-id="${b.id}"`):b.status==='completed'?receiptAction(b):'—'}</td></tr>`).join(''))}
function overview(){const paid=state.incomes.filter(x=>!x.archived).reduce((a,b)=>a+b.amountCents,0)/100,expense=state.expenses.filter(x=>!x.archived&&x.paymentStatus==='paid').reduce((a,b)=>a+b.totalCents,0),upcoming=state.bookings.filter(b=>['pending','confirmed'].includes(b.status)&&b.date>=today()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));content.innerHTML=`<div class="kpi-grid">${kpi('Citas de hoy',state.bookings.filter(b=>b.date===today()&&b.status!=='cancelled').length,'Hora local del salón','bookings')}${kpi('Ingresos',money(paid),'Cobros registrados · todo el historial','finance')}${kpi('Gastos',eu(expense),'Pagados · todo el historial','finance')}${kpi('Saldo',eu(Math.round(paid*100)-expense),'Ingresos menos pagos · todo el historial','finance')}</div><section class="panel table-panel">${toolbar('Próximas citas','Agenda del salón',btn('Todas las citas ↗','data-view="bookings"'))}${bookingTable(upcoming.slice(0,6))}</section><div class="lower-grid"><section class="panel mini-panel"><p class="eyebrow">MATERIALES Y COMPRAS</p><h3>Tu catálogo, a tu medida.</h3><p>Añade tintes, tratamientos y consumibles. Vincúlalos a proveedores y utilízalos en gastos y pedidos.</p>${btn('Ver materiales ↗','data-view="materials"')}</section><section class="panel mini-panel"><p class="eyebrow">DOCUMENTOS</p><h3>Cada original, junto a su operación.</h3><p>Facturas, recibos, contratos y capturas se guardan fuera del navegador y se incluyen en la exportación para tu asesoría.</p>${btn('Ver documentos ↗','data-view="documents"')}</section></div>`}
function bookings(){content.innerHTML=`<p class="settings-note">${state.bookings.filter(b=>b.status==='pending').length} solicitudes pendientes. Confirma, cambia la fecha o rechaza la solicitud. Las solicitudes pendientes reservan el horario.</p>`+`<section class="panel table-panel">${toolbar('Todas las citas','Sin pagos online',`<input id="search" aria-label="Buscar" placeholder="Cliente o servicio…" value="${esc(search)}">${btn('Actualizar','id="refresh-bookings"')}`)}${bookingTable(state.bookings.filter(b=>matches(b.name,b.phone,service(b.service))).sort((a,b)=>(b.status==='pending')-(a.status==='pending')||(a.date+a.time).localeCompare(b.date+b.time)))}</section>`;bindFilters();$('#refresh-bookings').onclick=refresh}
function clientView(){content.innerHTML=`<section class="panel table-panel">${toolbar('Base de clientes','Nombre, apellidos, teléfono, email e historial de citas',filterTools('clients','Cliente'))}${table(['Cliente','Teléfono','Email','Visitas','Pagado','Acciones'],active(state.clients).filter(c=>matches(fn(c),c.phone,c.email)).map(c=>{const rows=state.bookings.filter(b=>b.clientId===c.id);return `<tr><td><button class="row-action" data-client="${c.id}">${esc(fn(c))}</button>${c.archived?'<small>Archivado</small>':''}</td><td>${esc(c.phone)||'—'}</td><td>${esc(c.email)||'—'}</td><td>${rows.filter(b=>b.status==='completed').length}</td><td>${eu(state.incomes.filter(x=>!x.archived&&x.clientId===c.id).reduce((a,b)=>a+b.amountCents,0))}</td><td>${recordActions('clients',c)}</td></tr>`}).join(''))}</section>`;bindFilters()}
function materialView(){content.innerHTML=`<section class="panel table-panel">${toolbar('Catálogo de materiales','Precio orientativo sin impuestos. Cada gasto conserva el precio real de la compra.',filterTools('materials','Material'))}${table(['Material','Marca / referencia','Unidad','Precio','Proveedor','Acciones'],active(state.materials).filter(m=>matches(m.name,m.sku,m.brand)).map(m=>`<tr><td>${esc(m.name)}<small class="mobile-record-summary">${eu(m.priceCents)} / ${esc(m.unit)}</small>${m.archived?'<small>Archivado</small>':''}</td><td>${esc(m.brand)||'—'}<small>${esc(m.sku)}</small></td><td>${esc(m.unit)}</td><td>${eu(m.priceCents)}</td><td>${esc(state.suppliers.find(s=>s.id===m.supplierId)?.name)||'—'}</td><td>${btn('Gestionar',`data-manage-record="materials" data-id="${m.id}"`,'compact-button mobile-record-manage')}${recordActions('materials',m)}${!m.archived?btn('Añadir gasto',`data-expense-material="${m.id}"`):''}</td></tr>`).join(''),'materials')}</section>`;bindFilters()}
function supplierView(){content.innerHTML=`<section class="panel table-panel">${toolbar('Directorio de proveedores','Datos de contacto, datos fiscales y compras relacionadas',filterTools('suppliers','Proveedor'))}${table(['Proveedor','NIF / CIF','Contacto','Teléfono / email','Documentos','Acciones'],active(state.suppliers).filter(s=>matches(s.name,s.nif,s.phone,s.email)).map(s=>`<tr><td>${esc(s.name)}<small class="mobile-record-summary">${esc(s.phone||s.email)}</small>${s.archived?'<small>Archivado</small>':''}</td><td>${esc(s.nif)||'—'}</td><td>${esc(s.contact)||'—'}</td><td>${esc(s.phone)}<small>${esc(s.email)}</small></td><td>${btn('Adjuntar',`data-upload-type="suppliers" data-id="${s.id}"`)}</td><td>${btn('Gestionar',`data-manage-record="suppliers" data-id="${s.id}"`,'compact-button mobile-record-manage')}${recordActions('suppliers',s)}</td></tr>`).join(''),'suppliers')}</section>`;bindFilters()}
function periodTools(){return `<label class="period-label">Desde<input id="from" type="date" value="${from}"></label><label class="period-label">Hasta<input id="to" type="date" value="${to}"></label>`}
const inPeriod=d=>d>=from&&d<=to;
function bindPeriod(){for(const key of ['from','to'])$('#'+key).onchange=e=>{if(key==='from')from=e.target.value;else to=e.target.value;if(from>to){feedback('La fecha inicial debe ser anterior a la final.');return}render()}}
function finance(){
 const expenseRowsInPeriod=state.expenses.filter(x=>inPeriod(x.date)),incomeRowsInPeriod=state.incomes.filter(x=>inPeriod(x.date));
 const expenses=expenseRowsInPeriod.filter(x=>includeArchived||!x.archived),incomes=incomeRowsInPeriod.filter(x=>includeArchived||!x.archived);
 const total=expenseRowsInPeriod.filter(x=>!x.archived).reduce((a,b)=>a+b.totalCents,0),out=expenseRowsInPeriod.filter(x=>!x.archived&&x.paymentStatus==='paid'&&inPeriod(x.paidDate)).reduce((a,b)=>a+b.totalCents,0);
 const cashOut=state.expenses.filter(x=>!x.archived&&x.paymentStatus==='paid'&&inPeriod(x.paidDate)).reduce((a,b)=>a+b.totalCents,0),received=incomeRowsInPeriod.filter(x=>!x.archived).reduce((a,b)=>a+b.amountCents,0);
 content.innerHTML=`<div class="finance-entry-actions">${btn('+ Añadir ingreso','data-new="incomes"','button light')}${btn('+ Añadir gasto','data-new="expenses"','button')}</div><div class="period-bar">${periodTools()}${btn(includeArchived?'Ocultar archivo':'Mostrar archivo','id="toggle-archive"')}${btn('Paquete para asesoría ↓','id="export-package"')}${btn('Ingresos CSV ↓','id="export-incomes"')}${btn('Gastos CSV ↓','id="export-expenses"')}</div>
 <div class="kpi-grid">${kpi('Ingresos registrados',eu(received),'Añadir un ingreso recibido','incomes','new')}${kpi('Gastos documentados',eu(total),'Por fecha del documento','finance')}${kpi('Pagado a proveedores',eu(cashOut),'Por fecha de pago','finance')}${kpi('Saldo de cobros y pagos',eu(received-cashOut),'Ingresos menos pagos del periodo','finance')}</div>
 <section class="panel table-panel" id="income-register">${toolbar('Registro de ingresos','Cobros reales, con o sin cita. Las citas cobradas se incorporan una sola vez.')}${table(['<span class="desktop-table-label">Fecha</span><span class="mobile-table-label">Ingreso</span>','Concepto / categoría','Cliente','Importe recibido','Forma de cobro','Documentos / acciones'],incomes.sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt)).map(x=>{const booking=state.bookings.find(b=>b.id===x.bookingId);return `<tr><td>${esc(x.date)}<div class="mobile-record-summary">${esc(x.description)}</div><small>${esc(x.documentNumber)}</small>${x.archived?'<small>Archivado</small>':''}</td><td>${esc(x.description)}<small>${esc(x.category)}${booking?' · '+esc(service(booking.service)):''}</small></td><td>${esc(fn(state.clients.find(c=>c.id===x.clientId)||{}))||'Sin cliente vinculado'}${booking?'<small>Cobro de cita</small>':''}</td><td><strong>${eu(x.amountCents)}</strong>${btn('Gestionar',`data-manage-finance="incomes" data-id="${x.id}"`,'compact-button mobile-record-manage')}</td><td>${paymentMethods[x.paymentMethod]||esc(x.paymentMethod)}</td><td>${btn('Adjuntar +',`data-upload-type="incomes" data-id="${x.id}"`)}<small>${state.documents.filter(d=>!d.archived&&d.entityType==='incomes'&&d.entityId===x.id).length} archivos</small>${recordActions('incomes',x)}</td></tr>`}).join(''),'incomes')}<div class="finance-total"><span>Ingresos activos del periodo</span><strong>${eu(received)}</strong></div></section>
 <section class="panel table-panel">${toolbar('Registro de gastos','Introduce el impuesto según la factura. Tu asesoría revisa la deducibilidad.')}${table(['<span class="desktop-table-label">Fecha</span><span class="mobile-table-label">Gasto</span>','Categoría / material','Proveedor','Cantidad × precio','Impuesto','Total','Pago','Documentos / acciones'],expenses.map(x=>`<tr><td>${esc(x.date)}<div class="mobile-record-summary">${esc(x.description)}</div><small>${esc(x.invoiceNumber)}</small>${x.archived?'<small>Archivado</small>':''}</td><td>${esc(x.description)}<small>${esc(x.category)} · ${esc(x.materialSnapshot)}</small></td><td>${esc(x.supplierSnapshot)||'—'}</td><td>${x.quantity} ${esc(x.unit)} × ${eu(x.priceCents)}</td><td>${eu(x.taxCents)}</td><td><strong>${eu(x.totalCents)}</strong><small class="mobile-record-summary">${x.paymentStatus==='paid'?'Pagado':'Pendiente'}</small>${btn('Gestionar',`data-manage-finance="expenses" data-id="${x.id}"`,'compact-button mobile-record-manage')}</td><td><span class="status-tag ${x.paymentStatus==='paid'?'done':''}">${x.paymentStatus==='paid'?'Pagado':'Pendiente'}</span><small>${esc(x.paidDate)}</small></td><td>${btn('Adjuntar +',`data-upload-type="expenses" data-id="${x.id}"`)}<small>${state.documents.filter(d=>!d.archived&&d.entityType==='expenses'&&d.entityId===x.id).length} archivos</small>${recordActions('expenses',x)}</td></tr>`).join(''),'expenses')}<div class="finance-total"><span>Gastos activos por fecha del documento · pagados en el mismo periodo: ${eu(out)}</span><strong>${eu(total)}</strong></div></section>
 <p class="caption">El importe recibido incluye los impuestos que correspondan. No se calcula una tarifa ni se cobra online. Se conservan originales e historial de correcciones; el paquete incluye ingresos y gastos.</p>`;
 bindPeriod();bindFilters();$('#export-incomes').onclick=()=>download(new Blob(['\ufeff'+csv(incomeRows(incomeRowsInPeriod))],{type:'text/csv;charset=utf-8'}),'incomes.csv');$('#export-expenses').onclick=()=>download(new Blob(['\ufeff'+csv(expenseRows(expenseRowsInPeriod))],{type:'text/csv;charset=utf-8'}),'expenses.csv');$('#export-package').onclick=exportPackage;
}
function manageFinance(type,key){
 const r=state[type]?.find(x=>x.id===key);if(!r)return;if(dialog.open)dialog.close();
 const line=(label,value)=>`<div class="detail-line"><span>${label}</span><strong>${esc(value||'—')}</strong></div>`;
 const client=state.clients.find(c=>c.id===r.clientId),booking=state.bookings.find(b=>b.id===r.bookingId);
 const details=type==='incomes'?line('Importe recibido',eu(r.amountCents))+line('Categoría',r.category)+line('Cliente',client?fn(client):'Sin cliente vinculado')+line('Forma de cobro',paymentMethods[r.paymentMethod])+line('Documento',r.documentNumber)+(booking?line('Cita',`${booking.date} · ${booking.time} · ${service(booking.service)}`):'')+line('Notas',r.notes):line('Total',eu(r.totalCents))+line('Categoría',r.category)+line('Material',r.materialSnapshot)+line('Proveedor',r.supplierSnapshot)+line('Cantidad',`${r.quantity} ${r.unit}`)+line('Precio sin impuestos',eu(r.priceCents))+line('Base',eu(r.netCents))+line('Impuesto',eu(r.taxCents))+line('Pago',r.paymentStatus==='paid'?'Pagado':'Pendiente')+(r.paidDate?line('Fecha de pago',r.paidDate):'')+line('Factura / recibo',r.invoiceNumber);
 const docs=state.documents.filter(d=>!d.archived&&d.entityType===type&&d.entityId===key);
 $('#client-detail').innerHTML=`<p class="eyebrow">${type==='incomes'?'INGRESO':'GASTO'}${r.archived?' · ARCHIVADO':''}</p><h2>${esc(r.description)}</h2>${line('Fecha',r.date)}${details}<h3 class="record-docs-heading">Documentos (${docs.length})</h3><div class="record-documents">${docs.map(d=>`<a class="compact-button" href="/api/admin/documents/${d.id}">${esc(d.name)}</a>`).join('')||'<p class="caption">Sin documentos adjuntos.</p>'}</div><div class="booking-manage-actions">${!r.archived?btn('Editar',`data-edit="${type}" data-id="${key}"`):''}${btn('Adjuntar documento',`data-upload-type="${type}" data-id="${key}"`)}${btn(r.archived?'Restaurar':'Archivar',`data-archive="${type}" data-id="${key}"`)}</div>`;dialog.showModal();
}
function manageRecord(type,key){
 const r=state[type]?.find(x=>x.id===key);if(!r)return;if(dialog.open)dialog.close();
 const line=(label,value)=>`<div class="detail-line"><span>${label}</span><strong>${esc(value||'—')}</strong></div>`;
 let heading=r.name||r.reference,details='',actions='';
 if(type==='materials'){details=line('Marca',r.brand)+line('Referencia / tono',r.sku)+line('Unidad',r.unit)+line('Precio sin impuestos',eu(r.priceCents))+line('Proveedor',state.suppliers.find(x=>x.id===r.supplierId)?.name)+line('Notas',r.notes);actions=recordActions(type,r)+(!r.archived?btn('Añadir gasto',`data-expense-material="${key}"`):'');}
 if(type==='suppliers'){details=line('NIF / CIF',r.nif)+line('Contacto',r.contact)+line('Teléfono',r.phone)+line('Email',r.email)+line('Dirección',r.address)+line('Notas',r.notes);actions=recordActions(type,r)+btn('Adjuntar documento',`data-upload-type="${type}" data-id="${key}"`);}
 if(type==='orders'){details=line('Fecha',r.date)+line('Proveedor',JSON.parse(r.supplierSnapshot).name)+line('Estado',statuses[r.status])+line('Total sin impuestos',eu(r.totalCents))+r.lines.map(l=>line(l.name,`${l.quantity} ${l.unit} × ${eu(l.priceCents)} = ${eu(l.totalCents)}`)).join('')+line('Notas',r.notes);actions=(r.status==='draft'?btn('Editar',`data-edit="orders" data-id="${key}"`):'')+btn('Estado',`data-order-status="${key}"`)+btn('Imprimir / PDF',`data-print-order="${key}"`)+btn('Adjuntar documento',`data-upload-type="orders" data-id="${key}"`);}
 if(type==='documents'){details=line('Fecha',r.date)+line('Tipo',kinds[r.kind])+line('Número',r.number)+line('Vínculo',linkName(r))+line('Tamaño',`${(r.size/1024).toFixed(1)} KB`)+line('SHA-256',r.sha256)+line('Notas',r.notes);actions=`<a class="compact-button" href="/api/admin/documents/${key}">Descargar</a>`+btn('Datos del documento',`data-edit-document="${key}"`)+btn(r.archived?'Restaurar':'Archivar',`data-archive="documents" data-id="${key}"`);}
 $('#client-detail').innerHTML=`<p class="eyebrow">${esc(labels[type])}${r.archived?' · ARCHIVADO':''}</p><h2>${esc(heading)}</h2>${details}<div class="booking-manage-actions">${actions}</div>`;dialog.showModal();
}
function archiveRecord(type,key){
 const r=state[type].find(x=>x.id===key),action=r.archived?'restore':'archive',label=type==='incomes'?'ingreso':type==='expenses'?'gasto':'registro',needsReason=['incomes','expenses'].includes(type);
 openModal((r.archived?'Restaurar ':'Archivar ')+label,`<p class="caption span-2">${esc(r.description||r.name||r.reference||'')}. Se conservan el registro, los documentos y el historial.</p>`+field(needsReason?'Motivo de la corrección':'Motivo (opcional)','correctionReason','','text',`${needsReason?'required ':''}maxlength="1000"`),d=>api(type+'/'+key,'PUT',{action,revision:r.revision,correctionReason:d.get('correctionReason')}));
}
function editIncome(key,preset={}){
 const old=key?state.incomes.find(x=>x.id===key):null,r={...(old||{}),...preset},linked=state.bookings.find(b=>b.id===r.bookingId);
 const eligible=state.bookings.filter(b=>b.status==='completed'&&!receiptFor(b.id));
 const bookingField=old?(linked?`<p class="caption span-2">Cobro de ${esc(linked.name)} · ${esc(service(linked.service))} · ${esc(linked.date)}. Se conserva el vínculo con esta cita.</p>`:'') :select('Cita completada (opcional)','bookingId','<option value="">Ingreso sin cita</option>'+eligible.map(b=>`<option value="${b.id}" ${b.id===r.bookingId?'selected':''}>${esc(b.date)} · ${esc(b.name)} · ${esc(service(b.service))}</option>`).join(''));
 const html=bookingField+field('Fecha del cobro','date',r.date||today(),'date','required')+field('Concepto','description',r.description||(linked?service(linked.service):''),'text','required maxlength="1000"')+select('Categoría','category',['Servicios','Productos','Otros'].map(x=>`<option ${x===r.category?'selected':''}>${x}</option>`).join(''))+select('Cliente (opcional)','clientId',options(state.clients,fn,r.clientId||linked?.clientId))+field('Importe recibido, €','amount',r.amountCents===undefined?'':(r.amountCents/100).toFixed(2),'number','required min="0.01" max="1000000" step="0.01" inputmode="decimal"')+select('Forma de cobro','paymentMethod',Object.entries(paymentMethods).map(([v,l])=>`<option value="${v}" ${v===(r.paymentMethod||'cash')?'selected':''}>${l}</option>`).join(''))+field('Número de factura / justificante (si existe)','documentNumber',r.documentNumber,'text','maxlength="100"')+area('Notas','notes',r.notes)+(old?field('Motivo de la corrección','correctionReason','','text','required maxlength="1000"'):'')+`<p class="caption span-2">Registra únicamente dinero ya recibido. Si corresponde a una cita completada, selecciónala: el cobro quedará vinculado sin duplicarse. Puedes adjuntar el justificante después de guardar.</p>`;
 openModal(old?'Editar ingreso':'Añadir ingreso',html,d=>api('incomes'+(old?'/'+old.id:''),old?'PUT':'POST',{...Object.fromEntries(d),bookingId:old?old.bookingId:d.get('bookingId'),amountCents:Math.round(Number(d.get('amount'))*100),revision:old?.revision}));
 const f=$('#editor-form');function chooseBooking(){const b=old?linked:state.bookings.find(x=>x.id===f.elements.bookingId.value);f.elements.clientId.disabled=!!b;if(b){f.elements.clientId.value=b.clientId;f.elements.description.value=old?r.description:service(b.service);f.elements.category.value='Servicios'}}
 if(!old)f.elements.bookingId.onchange=chooseBooking;chooseBooking();
 if(old?.archived){$('#editor-form button[type=submit]').disabled=true;$('#form-error').textContent='Este ingreso está archivado. Restáuralo desde el registro antes de corregirlo.';}
}
function orderView(){content.innerHTML=`<p class="settings-note">El pedido es una lista de compra, no una factura fiscal. Puedes imprimirlo o guardarlo en PDF y enviarlo al proveedor. Preparar un pedido no genera un gasto automáticamente.</p><section class="panel table-panel">${toolbar('Pedidos a proveedores','Se conserva el nombre y el precio de cada artículo en el momento del pedido',filterTools('orders','Pedido'))}${table(['Número / fecha','Proveedor','Artículos','Importe sin impuestos','Estado','Acciones'],active(state.orders).filter(o=>matches(o.reference,JSON.parse(o.supplierSnapshot).name)).map(o=>`<tr><td>${esc(o.reference)}<small class="mobile-record-summary">${esc(JSON.parse(o.supplierSnapshot).name)} · ${eu(o.totalCents)} · ${statuses[o.status]}</small><small>${esc(o.date)}</small></td><td>${esc(JSON.parse(o.supplierSnapshot).name)}</td><td>${o.lines.length}</td><td>${eu(o.totalCents)}</td><td><span class="status-tag">${statuses[o.status]}</span></td><td>${btn('Gestionar',`data-manage-record="orders" data-id="${o.id}"`,'compact-button mobile-record-manage')}${o.status==='draft'?btn('Editar',`data-edit="orders" data-id="${o.id}"`):''}${btn('Estado',`data-order-status="${o.id}"`)}${btn('Imprimir / PDF',`data-print-order="${o.id}"`)}${btn('Adjuntar +',`data-upload-type="orders" data-id="${o.id}"`)}</td></tr>`).join(''),'orders')}</section>`;bindFilters()}
function linkName(d){if(d.entityType==='general')return 'Archivo general';const r=state[d.entityType]?.find(r=>r.id===d.entityId);return r?d.entityType==='clients'?fn(r):r.name||r.description||r.reference:'Registro vinculado'}
function documentView(){content.innerHTML=`<p class="settings-note">PDF, fotos y capturas de hasta 10 MB por archivo. Se conserva el original y su huella SHA-256. Cada nueva versión se sube por separado. Las facturas emitidas se incorporan desde tu sistema de facturación.</p><section class="panel table-panel">${toolbar('Archivo de documentos','La factura, el justificante de pago y el pedido se guardan como documentos distintos.',`<input id="search" aria-label="Buscar" placeholder="Archivo, número, tipo…" value="${esc(search)}">${btn(includeArchived?'Ocultar archivo':'Mostrar archivo','id="toggle-archive"')}${btn('+ Subir archivos','data-upload-type="general"')}`)}${table(['Fecha / tipo','Archivo','Número','Vínculo','Tamaño','Acciones'],active(state.documents).filter(d=>matches(d.name,d.number,kinds[d.kind],linkName(d))).map(d=>`<tr><td>${esc(d.date)}<div class="mobile-record-summary">${esc(d.name)}</div><small>${kinds[d.kind]||esc(d.kind)}</small></td><td>${esc(d.name)}<small title="${d.sha256}">SHA-256: ${d.sha256.slice(0,14)}…</small></td><td>${esc(d.number)||'—'}</td><td>${esc(linkName(d))}</td><td>${(d.size/1024).toFixed(1)} KB</td><td>${btn('Gestionar',`data-manage-record="documents" data-id="${d.id}"`,'compact-button mobile-record-manage')}<a class="compact-button" href="/api/admin/documents/${d.id}">Descargar ↓</a>${btn('Datos del documento',`data-edit-document="${d.id}"`)}${btn(d.archived?'Restaurar':'Archivar',`data-archive="documents" data-id="${d.id}"`)}</td></tr>`).join(''),'documents')}</section>`;bindFilters()}
function notificationView(){const t=state.telegram,w=state.whatsapp,current=state.notificationChannel;content.innerHTML=`<section class="panel mini-panel notification-channel"><p class="eyebrow">AVISOS DEL SALÓN</p><h3>Canal activo: ${current==='whatsapp'?'WhatsApp':'Telegram'}</h3><p>Las nuevas solicitudes se guardan primero en CRM y se envían al canal elegido. Los avisos anteriores conservan su canal y su historial.</p>${current!=='whatsapp'?btn('Activar WhatsApp para nuevas solicitudes',`id="activate-whatsapp" ${!w.configured||!w.verified||w.testPending?'disabled':''}`):btn('Volver a Telegram','id="activate-telegram"')}${btn('Actualizar estado','id="refresh-notifications"')}</section>
<section class="panel mini-panel whatsapp-settings"><p class="eyebrow">WHATSAPP · GRUPO DEL SALÓN</p><h3>${w.verified?'Conexión verificada':w.configured?'Vincula el grupo':'Preparar conexión de Olga'}</h3><p>Los avisos incluyen servicio, fecha, hora y referencia. No incluyen teléfonos ni emails de clientes. Para gestionar una solicitud, responde a su mensaje con <strong>Confirmar</strong> o <strong>Rechazar</strong>. Basta con pertenecer al grupo; Olga puede responder desde su propio teléfono.</p>${w.groupTitle?`<p>Grupo: <strong>${esc(w.groupTitle)}</strong></p>`:''}<p>${w.pending} avisos de WhatsApp pendientes.</p>${w.lastError?`<p role="status">${esc(w.lastError)}</p>`:''}
<details><summary>Cómo conectar el número de Olga</summary><p>GREEN-API se vincula como dispositivo de su cuenta de WhatsApp. El proveedor puede acceder a mensajes de esa cuenta, incluidos chats personales. Puede haber desconexiones o restricciones del número. La aplicación CULT SPAIN descarta los chats personales y los grupos que no se han seleccionado, sin guardarlos en CRM.</p><ol><li>La titular crea su cuenta e instancia en <a href="https://console.green-api.com/" target="_blank" rel="noopener noreferrer">GREEN-API</a> y autoriza la vinculación desde WhatsApp → Dispositivos vinculados.</li><li>Se guardan apiUrl, idInstance y apiTokenInstance en los ajustes protegidos de Cloudflare. Nunca envíes el token por un chat.</li><li>Genera el comando, envíalo al grupo del salón y comprueba la conexión.</li><li>Responde al mensaje de prueba con VERIFICAR. Después activa WhatsApp como canal de avisos.</li></ol><p>Desconectar el dispositivo desde WhatsApp revoca el acceso del proveedor.</p></details>
${!w.configured?'<p class="settings-note">Pendiente de vincular el número y guardar las credenciales. Telegram sigue funcionando.</p><details><summary>Ajustes para la instalación</summary><p>En Cloudflare, para el Worker CULT SPAIN: WHATSAPP_API_URL = apiUrl; WHATSAPP_INSTANCE_ID = idInstance; WHATSAPP_API_TOKEN = apiTokenInstance (tipo Secret).</p></details>':`<form id="whatsapp-pair-form"><label class="notification-consent"><input type="checkbox" name="authorized" required>Autorizo conectar la instancia exclusiva de Olga y enviar a CULT SPAIN los eventos del proveedor. Entiendo que el dispositivo vinculado puede acceder a sus chats.</label><button class="compact-button" type="submit">Generar comando de vinculación</button></form>${btn('Comprobar grupo','id="whatsapp-connect"')}${w.verified?btn('Reintentar avisos de WhatsApp','id="whatsapp-retry"'):''}`}
${w.testPending?'<p class="settings-note">Mensaje de prueba enviado al grupo. Responde a ESE mensaje con VERIFICAR y pulsa Actualizar estado. Telegram sigue activo hasta que elijas WhatsApp.</p>':''}<div id="whatsapp-connection"></div></section>`+`<section class="panel mini-panel"><p class="eyebrow">TELEGRAM · GRUPO DEL SALÓN</p><h3>${t.tokenSet&&t.connected?'Bot conectado':'Conecta tus avisos'}</h3><p>Las nuevas solicitudes y sus cambios se notifican al grupo. Incluyen servicio, fecha, hora y un enlace a la administración. No se envían teléfonos ni emails de clientes.</p>${t.groupTitle?`<p>Grupo: <strong>${esc(t.groupTitle)}</strong></p>`:''}<p>${t.pending} avisos pendientes de entrega.</p><p>${t.webhookEnabled?'Botones de confirmar y rechazar activados para los miembros del grupo.':'La confirmación desde Telegram todavía no está activada.'}</p>${t.lastError?`<p role="status">Último intento: ${esc(t.lastError)}</p>`:''}${!t.tokenSet?'<p>Añade TELEGRAM_BOT_TOKEN como secreto en Cloudflare. El token nunca se muestra en el sitio.</p>':btn(t.connected?'Vincular otro grupo':'Vincular grupo','id="telegram-pair"')}${t.tokenSet&&t.connected?btn('Reintentar avisos pendientes','id="telegram-retry"')+(!t.webhookEnabled?btn('Activar botones en Telegram','id="telegram-webhook"'):''):''}<div id="telegram-connection"></div></section>`;
 $('#refresh-notifications').onclick=refresh;
 if($('#activate-whatsapp'))$('#activate-whatsapp').onclick=()=>perform(()=>api('notifications/channel','PUT',{channel:'whatsapp'}),'WhatsApp activado para nuevas solicitudes.');
 if($('#activate-telegram'))$('#activate-telegram').onclick=()=>perform(()=>api('notifications/channel','PUT',{channel:'telegram'}),'Telegram activado para nuevas solicitudes.');
 if($('#whatsapp-pair-form'))$('#whatsapp-pair-form').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;try{const result=await api('whatsapp/pair','POST',{authorized:new FormData(e.currentTarget).has('authorized')});$('#whatsapp-connection').innerHTML=`<p>Envía este comando exacto al grupo del salón durante los próximos 10 minutos:</p><p><code>${esc(result.command)}</code></p><p>Después pulsa Comprobar grupo.</p>`}catch(error){feedback(error.message)}finally{button.disabled=false}};
 if($('#whatsapp-connect'))$('#whatsapp-connect').onclick=()=>perform(()=>api('whatsapp/connect','POST',{}),'Mensaje de prueba enviado. Responde VERIFICAR en el grupo.');
 if($('#whatsapp-retry'))$('#whatsapp-retry').onclick=()=>perform(()=>api('whatsapp/retry','POST',{}),'Reintento de WhatsApp completado.');
 if($('#telegram-webhook'))$('#telegram-webhook').onclick=()=>perform(()=>api('telegram/webhook','POST',{}),'Botones de Telegram activados.');
 if($('#telegram-retry'))$('#telegram-retry').onclick=()=>perform(()=>api('telegram/retry','POST',{}),'Reintento completado.');
 if($('#telegram-pair'))$('#telegram-pair').onclick=async()=>{const b=$('#telegram-pair');b.disabled=true;try{const p=await api('telegram/pair','POST',{});$('#telegram-connection').innerHTML=`<p>Añade <strong>@${esc(p.botUsername)}</strong> al grupo del salón y envía allí este comando (válido durante 10 minutos):</p><p><code>${esc(p.command)}</code></p><p>Después pulsa Comprobar conexión.</p>${btn('Comprobar conexión','id="telegram-connect"')}`;$('#telegram-connect').onclick=()=>perform(()=>api('telegram/connect','POST',{}),'Grupo conectado.')}catch(e){feedback(e.message)}finally{b.disabled=false}};
}
const days=['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
function schedule(){content.innerHTML=`<p class="settings-note">Horario de ejemplo. Los cambios se guardan en la base y se aplican al calendario de reservas. Margen entre citas: 15 minutos.</p><form id="week-form" class="panel table-panel">${toolbar('Horario habitual','Se repite cada semana')}<div class="table-scroll"><table class="schedule-table"><thead><tr><th>Día</th><th>Abierto</th><th>Desde</th><th>Hasta</th><th>Pausa desde</th><th>Hasta</th></tr></thead><tbody>${[1,2,3,4,5,6,0].map(i=>{const c=state.week[i];return `<tr><td>${days[i]}</td><td><input type="checkbox" name="open-${i}" aria-label="${days[i]}: día laborable" ${c.open?'checked':''}></td>${['start','end','breakStart','breakEnd'].map((k,n)=>`<td><input type="time" name="${k}-${i}" aria-label="${days[i]}: ${k}" value="${c[k]}" ${n<2?'required':''}></td>`).join('')}</tr>`}).join('')}</tbody></table></div><div class="table-actions"><small>Puedes dejar vacíos ambos campos de la pausa.</small><button class="button light">Guardar horario</button></div></form><section class="panel table-panel">${toolbar('Excepciones por fecha','Sustituye el horario solo en la fecha seleccionada')}<form id="exception-form" class="inline-form"><label>Fecha<input name="date" type="date" min="${today()}" value="${today()}" required></label><label>Modo<select name="mode"><option value="closed">Cerrado</option><option value="open">Horario especial</option></select></label><label>Desde<input name="start" type="time" value="10:00" required></label><label>Hasta<input name="end" type="time" value="17:00" required></label><button class="compact-button">Guardar excepción</button></form>${table(['Fecha','Modo','Horas','Acción'],Object.entries(state.exceptions).sort(([a],[b])=>a.localeCompare(b)).map(([d,c])=>`<tr><td>${esc(d)}</td><td>${c.open?'Horario especial':'Cerrado'}</td><td>${c.open?c.start+'–'+c.end:'Cerrado'}</td><td>${btn('Restaurar horario habitual',`data-reset-day="${d}"`)}</td></tr>`).join(''))}</section>`;$('#week-form').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.currentTarget),week=Array.from({length:7},(_,i)=>({open:d.has('open-'+i),start:d.get('start-'+i),end:d.get('end-'+i),breakStart:d.get('breakStart-'+i),breakEnd:d.get('breakEnd-'+i)}));await perform(()=>api('schedule','PUT',{week,exceptions:state.exceptions}),'Horario guardado.')};$('#exception-form').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.currentTarget),key=d.get('date');if(state.exceptions[key]&&!confirm('¿Sustituir la excepción de esta fecha?'))return;const c={open:d.get('mode')==='open',start:d.get('start'),end:d.get('end'),breakStart:'',breakEnd:''};await perform(()=>api('schedule','PUT',{week:state.week,exceptions:{...state.exceptions,[key]:c}}),'Excepción guardada.')};}
function field(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function area(label,name,value=''){return `<label class="span-2">${label}<textarea name="${name}" rows="3" maxlength="3000">${esc(value)}</textarea></label>`}
function select(label,name,html){return `<label>${label}<select aria-label="${esc(label)}" name="${name}">${html}</select></label>`}
function openModal(heading,html,onSubmit,onSaved){if(dialog.open)dialog.close();$('#client-detail').innerHTML=`<p class="eyebrow">CULT SPAIN · GESTIÓN</p><h2>${heading}</h2><form id="editor-form" class="editor-form">${html}<div class="span-2 form-footer"><p id="form-error" role="alert"></p><button class="button light" type="submit">Guardar</button></div></form>`;dialog.showModal();$('#editor-form').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button[type=submit]');try{b.disabled=true;const result=await onSubmit(new FormData(e.currentTarget));dialog.close();await refresh();feedback('Datos guardados.');if(onSaved)await onSaved(result)}catch(err){$('#form-error').textContent=err.message;b.disabled=false}}}
function rescheduleBooking(key){
 const row=state.bookings.find(x=>x.id===key);if(!row||!['pending','confirmed'].includes(row.status))return;
 if(dialog.open)dialog.close();
 const calendar={...state,bookings:state.bookings.filter(x=>x.id!==key)};
 openModal('Cambiar fecha y hora',`<p class="caption span-2"><strong>${esc(row.name)}</strong> · ${esc(service(row.service))}<br>Cita actual: ${esc(row.date)} · ${esc(row.time)} · ${row.duration} min<br>${esc(statuses[row.status])}</p>`+field('Nueva fecha','date',row.date<today()?today():row.date,'date',`required min="${today()}" max="${addDays(today(),90)}"`)+select('Hora disponible','time','')+`<p class="caption span-2">Se conservan el cliente y el servicio. Solo aparecen huecos libres dentro del horario, incluido el margen de 15 minutos. El cambio queda en el historial.</p>`,d=>api('bookings/'+key,'PUT',{action:'reschedule',date:d.get('date'),time:d.get('time'),expectedDate:row.date,expectedTime:row.time}));
 const form=$('#editor-form');form.elements.time.required=true;
 function updateTimes(){const times=slots(calendar,form.elements.date.value,{duration:row.duration});form.elements.time.innerHTML='<option value="">'+(times.length?'Selecciona una hora':'Sin horas disponibles')+'</option>'+times.map(t=>`<option value="${t}" ${form.elements.date.value===row.date&&t===row.time?'selected':''}>${t}</option>`).join('');}
 form.elements.date.onchange=updateTimes;updateTimes();
}
function edit(type,key,preset={},onSaved){if(type==='incomes')return editIncome(key,preset);const old=key?state[type].find(x=>x.id===key):null,r={...(old||{}),...preset};let html='';if(type==='clients')html=field('Nombre','firstName',r.firstName,'text','required maxlength="100"')+field('Apellidos','lastName',r.lastName,'text','maxlength="100"')+field('Teléfono','phone',r.phone,'tel','maxlength="30"')+field('Email','email',r.email,'email','maxlength="254"')+field('NIF (si se necesita para facturar)','nif',r.nif,'text','maxlength="30"')+field('Dirección de facturación','address',r.address,'text','maxlength="500"')+area('Notas','notes',r.notes);
if(type==='suppliers')html=field('Nombre del proveedor','name',r.name,'text','required maxlength="180"')+field('NIF / CIF','nif',r.nif,'text','maxlength="30"')+field('Persona de contacto','contact',r.contact)+field('Teléfono','phone',r.phone,'tel','maxlength="30"')+field('Email','email',r.email,'email')+field('Dirección','address',r.address,'text','maxlength="500"')+area('Notas','notes',r.notes);
if(type==='materials')html=field('Material, por ejemplo tinte 7/1','name',r.name,'text','required maxlength="180"')+field('Marca','brand',r.brand)+field('Referencia / tono','sku',r.sku)+field('Unidad: ud., tubo, ml…','unit',r.unit||'ud.','text','required maxlength="30"')+field('Precio unitario sin impuestos, €','price',r.priceCents===undefined?'':(r.priceCents/100).toFixed(2),'number','required min="0" max="1000000" step="0.01"')+select('Proveedor habitual','supplierId',options(state.suppliers,'name',r.supplierId))+area('Notas','notes',r.notes);
if(type==='expenses'){html=field('Fecha del documento / gasto','date',r.date||today(),'date','required')+select('Categoría','category',['Materiales','Alquiler','Publicidad','Equipamiento','Servicios','Otros'].map(x=>`<option ${x===r.category?'selected':''}>${x}</option>`).join(''))+select('Material del catálogo','materialId',options(state.materials,'name',r.materialId))+`<div class="catalog-inline">${btn('+ Crear material en el catálogo','type="button" id="new-material-from-expense"')}</div>`+select('Proveedor','supplierId',options(state.suppliers,'name',r.supplierId))+field('Descripción','description',r.description,'text','required maxlength="1000"')+field('Unidad','unit',r.unit||'ud.','text','required maxlength="30"')+field('Cantidad','quantity',r.quantity||1,'number','required min="0.001" max="100000" step="0.001"')+field('Precio unitario sin impuestos, €','price',r.priceCents===undefined?'':(r.priceCents/100).toFixed(2),'number','required min="0" max="1000000" step="0.01"')+field('Impuesto según factura, €','tax',(r.taxCents||0)/100,'number','required min="0" max="1000000" step="0.01"')+field('Número de factura / recibo','invoiceNumber',r.invoiceNumber)+select('Pago','paymentStatus',`<option value="unpaid" ${r.paymentStatus!=='paid'?'selected':''}>Pendiente</option><option value="paid" ${r.paymentStatus==='paid'?'selected':''}>Pagado (registro manual)</option>`)+field('Fecha de pago (si está pagado)','paidDate',r.paidDate||today(),'date')+select('Pedido vinculado (opcional)','orderId',options(state.orders,'reference',r.orderId))+`<div class="form-total" id="expense-total"></div>`+(old?field('Motivo de la corrección','correctionReason','','text','required maxlength="1000"'):'')}
if(type==='orders'){editOrder(old);return}
openModal((old?'Editar: ':'Añadir: ')+(type==='expenses'?'Gasto':labels[type]),html,async d=>{const b=Object.fromEntries(d);if(old)b.revision=old.revision;if(type==='materials'){b.priceCents=Math.round(Number(b.price)*100);delete b.price}if(type==='expenses'){b.priceCents=Math.round(Number(b.price)*100);b.taxCents=Math.round(Number(b.tax)*100);b.quantity=Number(b.quantity);delete b.price;delete b.tax}return await api(type+(old?'/'+old.id:''),old?'PUT':'POST',b)},onSaved);
if(type==='expenses'){const f=$('#editor-form'),selectMaterial=f.elements.materialId;$('#new-material-from-expense').onclick=()=>{const d=Object.fromEntries(new FormData(f)),draft={...d,quantity:Number(d.quantity),priceCents:Math.round(Number(d.price)*100),taxCents:Math.round(Number(d.tax)*100)};dialog.close();edit('materials',null,{name:d.description,unit:d.unit,priceCents:draft.priceCents,supplierId:d.supplierId},result=>edit('expenses',key,{...draft,materialId:result.id}))};selectMaterial.onchange=()=>{const m=state.materials.find(m=>m.id===selectMaterial.value);if(m){f.elements.description.value=m.name;f.elements.unit.value=m.unit;f.elements.price.value=(m.priceCents/100).toFixed(2);f.elements.supplierId.value=m.supplierId||''}calcExpense()};for(const n of ['quantity','price','tax'])f.elements[n].oninput=calcExpense;calcExpense()}}
function calcExpense(){const f=$('#editor-form'),net=Math.round(Number(f.elements.quantity.value)*Number(f.elements.price.value)*100),tax=Math.round(Number(f.elements.tax.value)*100);$('#expense-total').innerHTML=`Sin impuestos: <strong>${eu(net)}</strong> · Impuesto: <strong>${eu(tax)}</strong><br>Total: <strong>${eu(net+tax)}</strong>`}
function editOrder(old){const html=field('Fecha del pedido','date',old?.date||today(),'date','required')+select('Proveedor','supplierId',options(state.suppliers,'name',old?.supplierId))+`<div class="span-2" id="order-lines"></div><div class="span-2">${btn('+ Artículo','type="button" id="add-order-line"')}</div>`+area('Comentario para el proveedor','notes',old?.notes);openModal(old?'Editar pedido':'Nuevo pedido al proveedor',html,async d=>{const lines=[...document.querySelectorAll('.order-line')].map(row=>({materialId:row.querySelector('[name=material]').value,quantity:Number(row.querySelector('[name=qty]').value),priceCents:Math.round(Number(row.querySelector('[name=price]').value)*100)}));await api('orders'+(old?'/'+old.id:''),old?'PUT':'POST',{date:d.get('date'),supplierId:d.get('supplierId'),notes:d.get('notes'),lines,status:'draft',revision:old?.revision})});function addLine(l={}){const div=document.createElement('div');div.className='order-line';div.innerHTML=select('Material','material',options(state.materials,'name',l.materialId))+field('Cantidad','qty',l.quantity||1,'number','required min="0.001" step="0.001"')+field('Precio sin impuestos, €','price',(l.priceCents||0)/100,'number','required min="0" step="0.01"')+btn('×','type="button" aria-label="Quitar artículo"','remove-line');$('#order-lines').append(div);div.querySelector('select').onchange=e=>{const m=state.materials.find(m=>m.id===e.target.value);if(m)div.querySelector('[name=price]').value=(m.priceCents/100).toFixed(2)};div.querySelector('button').onclick=()=>div.remove()}$('#add-order-line').onclick=()=>addLine();if(old)old.lines.forEach(addLine);else addLine()}
function uploadModal(type='general',key=''){openModal('Adjuntar documentos',select('Tipo de documento','kind',Object.entries(kinds).map(([v,l])=>`<option value="${v}">${l}</option>`).join(''))+field('Fecha del documento','date',today(),'date','required')+field('Número de documento (si existe)','number')+`<label class="span-2">Originales PDF / JPG / PNG / WebP<input name="files" type="file" accept="application/pdf,image/jpeg,image/png,image/webp" multiple required></label>`+area('Notas','notes'),async d=>{for(const file of d.getAll('files')){const form=new FormData();form.set('file',file);for(const n of ['kind','date','number','notes'])form.set(n,d.get(n));form.set('entityType',type);form.set('entityId',key);await api('documents','POST',form)}})}
function editDocument(key){const r=state.documents.find(x=>x.id===key);openModal('Datos del documento',select('Tipo','kind',Object.entries(kinds).map(([v,l])=>`<option value="${v}" ${v===r.kind?'selected':''}>${l}</option>`).join(''))+field('Fecha','date',r.date,'date','required')+field('Número','number',r.number)+area('Notas','notes',r.notes)+`<p class="caption span-2">El archivo original se conserva sin cambios. SHA-256: ${r.sha256}</p>`,d=>api('documents/'+r.id,'PUT',{...Object.fromEntries(d),revision:r.revision}))}
function showBooking(key){
 const row=state.bookings.find(b=>b.id===key);if(!row)return;
 if(dialog.open)dialog.close();
 const actions=['pending','confirmed'].includes(row.status)?(row.status==='pending'?btn('Confirmar',`data-booking="confirm" data-id="${row.id}"`):'')+btn('Cambiar fecha / hora',`data-booking="reschedule" data-id="${row.id}"`)+(row.status==='confirmed'?btn('Completar',`data-booking="complete" data-id="${row.id}"`):'')+btn(row.status==='pending'?'Rechazar':'Cancelar',`data-booking="cancel" data-id="${row.id}"`):row.status==='completed'?receiptAction(row):'';
 $('#client-detail').innerHTML=`<p class="eyebrow">GESTIONAR CITA</p><h2>${esc(row.name)}</h2><div class="detail-line"><span>Fecha y hora</span><strong>${esc(row.date)} · ${esc(row.time)}</strong></div><div class="detail-line"><span>Servicio</span><span>${esc(service(row.service))}</span></div><div class="detail-line"><span>Estado</span><span>${esc(statuses[row.status])}</span></div><div class="detail-line"><span>Teléfono</span><span>${esc(row.phone)}</span></div><p>${btn('Ver ficha del cliente',`data-client="${row.clientId}"`)}</p><div class="booking-manage-actions">${actions}</div>`;
 dialog.showModal();
}
function showClient(key){if(dialog.open)dialog.close();const r=state.clients.find(x=>x.id===key);if(!r)return;$('#client-detail').innerHTML=`<p class="eyebrow">FICHA DE CLIENTE</p><h2>${esc(fn(r))}</h2><div class="detail-line"><span>Teléfono</span><span>${esc(r.phone)}</span></div><div class="detail-line"><span>Email</span><span>${esc(r.email)}</span></div><div class="detail-line"><span>Notas</span><span>${esc(r.notes)}</span></div><p style="margin-top:20px">${btn('Editar ficha',`data-edit="clients" data-id="${r.id}"`)}</p>${bookingTable(state.bookings.filter(b=>b.clientId===key))}`;dialog.showModal()}
async function perform(action,message='Guardado.'){try{await action();await refresh();feedback(message)}catch(e){feedback(e.message)}}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000)}
const csv=rows=>rows.map(r=>r.map(v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}).join(';')).join('\r\n');
function incomeRows(rows){return [['ID','Fecha de cobro','Concepto','Categoría','Cliente ID','Cita ID','Importe recibido EUR','Forma de cobro','Número de documento','Notas','Archivado'],...rows.map(x=>[x.id,x.date,x.description,x.category,x.clientId,x.bookingId,(x.amountCents/100).toFixed(2),paymentMethods[x.paymentMethod],x.documentNumber,x.notes,x.archived])]}
function expenseRows(rows){return [['ID','Fecha','Categoría','Descripción','Material','Proveedor','Cantidad','Ud.','Precio sin impuesto EUR','Base EUR','Impuesto EUR','Total EUR','Número de factura','Estado de pago','Fecha de pago','Archivado'],...rows.map(x=>[x.id,x.date,x.category,x.description,x.materialSnapshot,x.supplierSnapshot,x.quantity,x.unit,(x.priceCents/100).toFixed(2),(x.netCents/100).toFixed(2),(x.taxCents/100).toFixed(2),(x.totalCents/100).toFixed(2),x.invoiceNumber,x.paymentStatus,x.paidDate,x.archived])]}
async function exportPackage(){const b=$('#export-package');b.disabled=true;try{feedback('Preparando documentos y registros…');const rows=state.expenses.filter(x=>inPeriod(x.date)),receipts=state.incomes.filter(x=>inPeriod(x.date)),ids=new Set(rows.map(x=>x.id)),incomeIds=new Set(receipts.map(x=>x.id)),docs=state.documents.filter(d=>inPeriod(d.date)||d.entityType==='expenses'&&ids.has(d.entityId)||d.entityType==='incomes'&&incomeIds.has(d.entityId)),files=[{name:'incomes.csv',data:'\ufeff'+csv(incomeRows(receipts))},{name:'expenses.csv',data:'\ufeff'+csv(expenseRows(rows))},{name:'clients.csv',data:'\ufeff'+csv([['ID','Nombre','Apellidos','Teléfono','Email','NIF','Dirección'],...state.clients.map(c=>[c.id,c.firstName,c.lastName,c.phone,c.email,c.nif,c.address])])},{name:'suppliers.json',data:JSON.stringify(state.suppliers,null,2)},{name:'materials.json',data:JSON.stringify(state.materials,null,2)},{name:'orders.json',data:JSON.stringify(state.orders.filter(o=>inPeriod(o.date)),null,2)},{name:'documents.json',data:JSON.stringify(docs,null,2)},{name:'audit.json',data:JSON.stringify(await api('audit'),null,2)},{name:'README.txt',data:`CULT SPAIN · Exportación ${from} — ${to}.\nIngresos seleccionados por fecha de cobro y gastos por fecha del documento, incluido el archivo para revisar el historial; los registros archivados no se suman a los informes.\nDocumentos: fecha dentro del periodo o vínculo con un ingreso o gasto del periodo. Los importes no implican deducibilidad fiscal automática.\nPaquete para asesoría. No es una declaración presentada. Huellas SHA-256 de originales en documents.json.\n`}];for(const d of docs){const r=await fetch('/api/admin/documents/'+d.id);if(!r.ok)throw Error('No se ha podido obtener el archivo '+d.name);files.push({name:'documents/'+d.id+'-'+d.name.replace(/[^\p{L}\p{N}._ -]/gu,'_'),data:new Uint8Array(await r.arrayBuffer())})}download(await zipFiles(files),`cult-accounting-${from}-${to}.zip`);feedback('Paquete para asesoría preparado.')}catch(e){feedback(e.message)}finally{b.disabled=false}}
function printOrder(key){const o=state.orders.find(x=>x.id===key),s=JSON.parse(o.supplierSnapshot),w=window.open('','_blank');if(!w)return feedback('Permite abrir la ventana para imprimir el pedido.');w.document.write(`<!doctype html><html lang="es"><meta charset="utf-8"><title>${esc(o.reference)}</title><style>body{font:14px Arial;margin:50px;color:#111}h1{font-size:26px}table{width:100%;border-collapse:collapse;margin:30px 0}th,td{padding:12px;border-bottom:1px solid #ccc;text-align:left}.muted{color:#555}button{padding:10px 20px}@media print{button{display:none}}</style><h1>CULT SPAIN · Pedido de compra</h1><p>${esc(o.reference)} · ${esc(o.date)}</p><p class="muted">Documento de pedido. No es una factura fiscal. No se ha enviado al proveedor.</p><h3>Proveedor: ${esc(s.name)}</h3><p>NIF/CIF: ${esc(s.nif)}<br>${esc(s.address)}<br>${esc(s.email)} · ${esc(s.phone)}</p><table><thead><tr><th>Material</th><th>Cantidad</th><th>Precio sin impuesto</th><th>Importe</th></tr></thead><tbody>${o.lines.map(l=>`<tr><td>${esc(l.name)}</td><td>${l.quantity} ${esc(l.unit)}</td><td>${eu(l.priceCents)}</td><td>${eu(l.totalCents)}</td></tr>`).join('')}</tbody></table><h3>Total sin impuestos: ${eu(o.totalCents)}</h3><p>${esc(o.notes)}</p><button onclick="window.print()">Imprimir / Guardar PDF</button></html>`);w.document.close()}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const key=b.dataset.id;if(b.dataset.view)return switchView(b.dataset.view);if(b.dataset.manageRecord)return manageRecord(b.dataset.manageRecord,key);if(b.dataset.manageFinance)return manageFinance(b.dataset.manageFinance,key);if(b.dataset.new)return edit(b.dataset.new);if(b.dataset.newIncomeBooking)return editIncome(null,{bookingId:b.dataset.newIncomeBooking});if(b.dataset.edit){if(dialog.open)dialog.close();return edit(b.dataset.edit,key)}if(b.dataset.manageBooking)return showBooking(b.dataset.manageBooking);if(b.dataset.client)return showClient(b.dataset.client);if(b.dataset.expenseMaterial){const m=state.materials.find(m=>m.id===b.dataset.expenseMaterial);return edit('expenses',null,{category:'Materiales',materialId:m.id,supplierId:m.supplierId,description:m.name,priceCents:m.priceCents,unit:m.unit})}if(b.dataset.uploadType)return uploadModal(b.dataset.uploadType,key||'');if(b.dataset.editDocument)return editDocument(b.dataset.editDocument);if(b.dataset.printOrder)return printOrder(b.dataset.printOrder);if(b.dataset.archive)return archiveRecord(b.dataset.archive,key);if(b.dataset.booking){if(b.dataset.booking==='reschedule')return rescheduleBooking(key);if(b.dataset.booking==='pay'){openModal('Registrar cobro en el salón',field('Importe recibido, €','amount','','number','required min="0.01" max="1000000" step="0.01"')+`<p class="caption span-2">Introduce el importe realmente recibido en el salón. No hay una tarifa automática ni un pago online.</p>`,d=>api('bookings/'+key,'PUT',{action:'pay',paidCents:Math.round(Number(d.get('amount'))*100),date:today()}));return}if(b.dataset.booking==='confirm'){if(dialog.open)dialog.close();const row=state.bookings.find(x=>x.id===key);return perform(()=>api('bookings/'+key,'PUT',{action:'confirm',expectedDate:row.date,expectedTime:row.time,expectedStatus:'pending'}),'Cita confirmada.');}if(b.dataset.booking==='cancel'){const row=state.bookings.find(x=>x.id===key);if(dialog.open)dialog.close();const label=row.status==='pending'?'Rechazar solicitud':'Cancelar cita';openModal(label,`<p class="caption span-2"><strong>${esc(row.name)}</strong><br>${esc(row.date)} · ${esc(row.time)} · ${esc(service(row.service))}<br>Se libera el horario y se conserva la cita en el historial.</p>`+area('Motivo (opcional)','reason'),d=>api('bookings/'+key,'PUT',{action:'cancel',reason:d.get('reason'),expectedDate:row.date,expectedTime:row.time,expectedStatus:row.status}));$('#editor-form button[type=submit]').textContent=label;return;}if(dialog.open)dialog.close();return perform(()=>api('bookings/'+key,'PUT',{action:b.dataset.booking,date:today()}),'Cita actualizada.')}if(b.dataset.resetDay){const x={...state.exceptions};delete x[b.dataset.resetDay];return perform(()=>api('schedule','PUT',{week:state.week,exceptions:x}),'Horario habitual restaurado.')}if(b.dataset.orderStatus){const o=state.orders.find(x=>x.id===b.dataset.orderStatus);openModal('Estado del pedido',select('Estado','status',Object.entries(statuses).filter(([k])=>['draft','ordered','received','cancelled'].includes(k)).map(([v,l])=>`<option value="${v}" ${o.status===v?'selected':''}>${l}</option>`).join('')),d=>api('orders/'+o.id,'PUT',{action:'status',status:d.get('status'),supplierId:o.supplierId,revision:o.revision}))}});
